#pragma once#include "IParameterReader.h"#include "ISignalTags.h"#include <map>#include <string>#include <vector>#include "ParsingHelp.h"#include <fstream>class KReadParamsFromEMF{public:  KReadParamsFromEMF(void);  virtual ~KReadParamsFromEMF(void);  BOOL ReadBlockParameters(LPCTSTR lpszPathName);  BOOL ReadSignalTags1_1000(LPCTSTR lpszPathName, LPCSTR lpszCsvComment);  BOOL ReadSignalTags1_4000(LPCTSTR lpszPathName, LPCSTR lpszCsvComment);  void ReadSignalTagsFromCsv( LPCSTR lpszCsvComment );  BOOL ReadVariables(LPCTSTR lpszPathName, LPCSTR lpszCsvComment);  void ReadVariablesFromCsv( LPCSTR lpszCsvComment );  void ReadAllSignalTagsVariables( LPCTSTR lpszPathName );  void AddManual( LPCSTR pszName, LPCSTR pszType );  void WriteBlocksByType( LPCTSTR lpszPathName, LPCSTR lpszType, CHAR sep = ',' );  BOOL IsPresentElement( LPCSTR lpszElName );  std::string GetElementType( LPCSTR lpszElName, BOOL *pbIsSimple = NULL );  int GetExecOrder( LPCSTR lpszElName );  void GetElementSettings( LPCSTR lpszElName, tVectoredString_ &sets, tParamsCont_ &params );  void GetNumericVariables( std::map<int, std::string> &set );  void ExtractInitialValue( LPCSTR pszPath, LPCSTR pszDigitalCsv, LPCSTR pszAnalogCsv );  std::string GetElementDescription( LPCSTR lpszElName );  std::string GetElementUnits( LPCSTR lpszElName );  void ConvertIO2Y( LPCSTR pszIoFila, LPCSTR pszYoutFile );  std::string GetRawInitialValue( LPCSTR pszPath, int var0A_var1D );  int GetSignalNumber( LPCSTR lpszElName );  int GetVariableNumber( LPCSTR lpszElName );protected:  int RecursiveRead(LPCTSTR lpszPathName);  void ReadSingleEmf(LPCTSTR lpszFileName);  void SingleTextLineBlockParameters(LPCSTR lpszText, RECTL *rc );  IParameterReadPtr CreateReader(LPCTSTR lpszText, RECTL *rc);  void SingleTextLineSignalTags(LPCSTR lpszText, RECTL *rc);  void SingleTextVariables(LPCSTR lpszText, RECTL *rc);  struct SReplaces  {    char from;    char to;  };  static SReplaces replaces[2];  template<class T, class Ti>  void AppendCommentTo( LPCSTR lpszCsvComment, T &cont )  {    CVSRow csvReader(',');    ifstream Fd( lpszCsvComment, std::ios_base::in);    while( Fd >> csvReader )    {      if( 0!=csvReader[0].find( "0x") )        continue;      string name = csvReader[3];      Ti itS = cont.find( name );      if( !name.compare("INVALIDTAG") )        continue;      if( itS==cont.end() )      {        for( int i=0; i<_countof(replaces); i++ )        {          string nName = name;          size_t pF = nName.find( replaces[i].from );          if( string::npos==pF )            continue;          nName.replace( pF, 1, 1, replaces[i].to );          itS = cont.find( nName );          if( itS!=cont.end() )            break;        }        if( itS==cont.end() )          continue;      }      string comment = csvReader[4];      itS->second->SetDescription( comment.c_str() );      string units = csvReader[9];      itS->second->SetUnits( units.c_str() );    }  }protected:  //для разбора FBDs  typedef std::map<std::string, IParamReaderFactoryPtr> tReadersFactory;  typedef std::map<std::string, IParameterReadPtr> tNamedElements;  //  typedef std::vector<std::string> tReadLineParams;  //для разбора SignalTags  typedef std::map<std::string, ISignalTagPtr> tNamedSignalTags;  //для разбора Variables  typedef std::map<std::string, ISignalTagPtr> tNamedVariables;  void(KReadParamsFromEMF::*m_fnLineParser)(LPCSTR, RECTL *);  typedef std::map<int, ISignalTagPtr> tNumberedVarCont;  //для FBDs  tReadersFactory m_ReadersFactory;  IParameterReadPtr m_curReader;  tNamedElements m_Elements;  //для SignalTags  tNamedSignalTags m_SignalTags;  tNamedVariables m_Variables;  tNumberedVarCont m_numberedVars;  //  tReadLineParams m_readLine;  int m_idSkipText;  typedef std::vector<char> tBinBuffer;  tBinBuffer m_cdeBuf;};